pi_section('Domain 4: Multi-Agent Orchestration & Handoff State');

$supervisor = new Pi_Chatbot_Supervisor_Agent();
pi_check('4.1 Supervisor routing price -> sales', $supervisor->route_intent('Báo giá', 'price') === 'sales');
pi_check('4.2 Supervisor routing project -> tech_spec', $supervisor->route_intent('Dự án bếp', 'project') === 'tech_spec');
pi_check('4.3 Supervisor routing contact -> lead_capture', $supervisor->route_intent('Liên hệ', 'contact') === 'lead_capture');
pi_check('4.4 Supervisor routing service -> warranty', $supervisor->route_intent('Bảo hành', 'service') === 'warranty');

$state4_5 = new Pi_Chatbot_Handoff_State('sess_4_5', 'supervisor');
$state4_5->active_agent_id = 'sales';
$state4_5->turn_count = 3;
$state4_5->save();
$state4_5_loaded = Pi_Chatbot_Handoff_State::load('sess_4_5');
pi_check('4.5 Transient save and load persistence', $state4_5_loaded->active_agent_id === 'sales' && $state4_5_loaded->turn_count === 3);
delete_transient('pi_cb_agent_state_' . md5('sess_4_5'));

$state4_6 = new Pi_Chatbot_Handoff_State('sess_4_6', 'supervisor');
$state4_6->user_message = 'Hỏi giá bếp gas';
$state4_6->save();
$state4_6_loaded = Pi_Chatbot_Handoff_State::load('sess_4_6');
pi_check('4.6 user_message preservation across turns', $state4_6_loaded->user_message === 'Hỏi giá bếp gas');
delete_transient('pi_cb_agent_state_' . md5('sess_4_6'));

$state4_7 = new Pi_Chatbot_Handoff_State('sess_4_7', 'supervisor');
for ($i = 0; $i < 6; $i++) {
    $state4_7->handoff_to('sales');
}
pi_check('4.7 Handoff max depth guard capping at 5 handoffs', $state4_7->active_agent_id === 'supervisor');

$sales_agent = new Pi_Chatbot_Sales_Agent();
$state4_8 = new Pi_Chatbot_Handoff_State('sess_4_8', 'sales');
