pi_section('Domain 5: Knowledge Graph & Persona Engine');

global $wpdb;
$session_5 = 'sess_graph_test_' . wp_rand(1000, 9999);
$u_node_id = Pi_Chatbot_Graph_Store::upsert_node('User_Test5', 'user', ['session_id' => $session_5]);
pi_check('5.1 User node creation in wp_pi_chatbot_nodes', $u_node_id > 0);

$p_node_id = Pi_Chatbot_Graph_Store::upsert_node('Hoshizaki', 'preference', ['attribute' => 'brand']);
pi_check('5.2 Product preference node creation', $p_node_id > 0);

$edge_id = Pi_Chatbot_Graph_Store::upsert_edge($u_node_id, $p_node_id, 'prefers_brand', 1.0);
pi_check('5.3 Edge creation in wp_pi_chatbot_edges', $edge_id > 0);

$neighborhood = Pi_Chatbot_Graph_Store::get_neighborhood($u_node_id);
pi_check('5.4 Graph 1-hop BFS neighborhood lookup', is_array($neighborhood) && count($neighborhood) > 0);

$wpdb->replace(Pi_Chatbot_Graph_Store::persona_table(), [
    'session_id' => $session_5,
    'user_id' => 0,
    'persona_node_id' => $u_node_id,
    'behavior_summary' => 'Prefers Hoshizaki brand',
    'updated_at' => current_time('mysql')
]);
$persona_prompt = Pi_Chatbot_Graph_Store::build_persona_prompt($session_5);
pi_check('5.5 Persona prompt formatting', strpos($persona_prompt, '<<<USER_GRAPH_PERSONA>>>') !== false);

Pi_Chatbot_Episodic_Memory::remember($session_5, ['preferred_brand' => 'Rational']);
$recalled = Pi_Chatbot_Episodic_Memory::recall($session_5);
pi_check('5.6 Entity triple extraction from episodic memory', isset($recalled['preferred_brand']) && $recalled['preferred_brand'] === 'Rational');

$re_edge_id = Pi_Chatbot_Graph_Store::upsert_edge($u_node_id, $p_node_id, 'prefers_brand', 0.5);
pi_check('5.7 Duplicate edge weight accumulation idempotency', $re_edge_id === $edge_id);

Pi_Chatbot_Graph_Store::create_tables();
$t_nodes = Pi_Chatbot_Graph_Store::nodes_table();
pi_check('5.8 Table creation via dbDelta', $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $t_nodes)) === $t_nodes);

$wpdb->update(Pi_Chatbot_Graph_Store::persona_table(), ['demographics' => json_encode(['budget' => 'High'])], ['session_id' => $session_5]);
$saved_persona = $wpdb->get_var($wpdb->prepare("SELECT demographics FROM " . Pi_Chatbot_Graph_Store::persona_table() . " WHERE session_id = %s", $session_5));
pi_check('5.9 Persona demographics update', strpos($saved_persona, 'High') !== false);

$enhanced_prompt = Pi_Chatbot_Generator::build_system_prompt('product', 'easy') . "\n" . $persona_prompt;
pi_check('5.10 System prompt enhancement with graph persona', strpos($enhanced_prompt, '<<<USER_GRAPH_PERSONA>>>') !== false);

// Cleanup graph test data
$wpdb->query("DELETE FROM " . Pi_Chatbot_Graph_Store::edges_table() . " WHERE id = {$edge_id}");
$wpdb->query("DELETE FROM " . Pi_Chatbot_Graph_Store::nodes_table() . " WHERE id IN ({$u_node_id}, {$p_node_id})");
$wpdb->delete(Pi_Chatbot_Graph_Store::persona_table(), ['session_id' => $session_5]);


